contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(amount1 <= address(this).balance, "insufficient balance for amount1");
        require(amount2 <= address(this).balance - amount1, "insufficient balance for amount2");

        c.addToBalance{value: amount1}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.addToBalance{value: amount2}(); if (__ESBMC_reverted()) return;
        uint balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(balAfter == balBefore + amount2 && cBalAfter == cBalBefore + amount2);
    }

    receive() external payable {}
}

